<div class="dzn-tp-capacity-grid"><?php $capacity_groups=array();foreach($catalogue as $course_row){$capacity_groups[(int)$course_row->instrument_id][]=$course_row;}$has_selected_course=false;foreach($capacity_groups as $capacity_rows):$selected_rows=array_values(array_filter($capacity_rows,static fn($row)=>(bool)$row->selected));if(!$selected_rows)continue;$has_selected_course=true;$course=$selected_rows[0];$occupied=(int)$course->default_duration_minutes+(int)$course->default_buffer_minutes;$count=$occupied>0?(int)floor($weekly_minutes/$occupied):0;$golden_count=$occupied>0?(int)floor($golden_minutes/$occupied):0;?><article><h3><?php echo esc_html($course->instrument); ?></h3><p><strong><?php echo esc_html(number_format_i18n($count)); ?></strong> کلاس برآوردی در هفته</p><p><strong><?php echo esc_html(number_format_i18n($golden_count)); ?></strong> کلاس بالقوه در ساعت طلایی</p><small><?php echo esc_html($course->default_duration_minutes.' دقیقه درس + '.$course->default_buffer_minutes.' دقیقه فاصله'); ?></small></article><?php endforeach;?><?php if(!$has_selected_course):?><p class="dzn-tp-help">برای دیدن برآورد ظرفیت، دست‌کم یک ساز قابل تدریس انتخاب کنید.</p><?php endif;?></div></section>

